  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In mice, Vistusertib, a polar methoxy- and acid-containing molecule, showed brain/plasma ratios below 5%, demonstrating that high polarity and ionizable groups can produce effectively impermeable BBB behavior despite systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "SMB-1, a small polar molecule with ionizable sulfonate and amide groups, showed low membrane permeability and poor CNS distribution in rats, supporting that the query's phosphinic acid, carboxylic acid, and amine functionalities are associated with inadequate brain access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Merck-3, a peptidomimetic with multiple polar groups and a basic amine, was a P-glycoprotein substrate with brain concentrations below the limit of detection despite micromolar plasma levels, directly supporting efflux liability and poor brain penetration for similarly ionizable/amine-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Human PET imaging with [11C]AcL703 showed low regional brain uptake, providing translational evidence that polar/ionizable molecules can fail to achieve meaningful CNS access in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Rat whole-body autoradiography after oral dosing of a highly polar phosphate-containing compound showed extremely low brain uptake, supporting that phosph(on)ate-like polar functionality limits CNS penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, ionizable ampholyte containing phosphinic acid, carboxylic acid, and basic amine groups. All high-transfer experimental analogues consistently demonstrate poor BBB penetration, low brain uptake, or efflux-substrate behavior. Therefore meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or transporter measurement is available for the exact query molecule.",
    "No human pharmacokinetic or PET data exist for the query itself.",
